<?php require_once 'funciones.php'; $n=(int)$conn->query("SELECT COUNT(*) c FROM usuarios WHERE rol='admin'")->fetch_assoc()['c']; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$n===0){$nombre=trim($_POST['nombre']??'');$usuario=trim($_POST['usuario']??'');$pass=$_POST['pass']??'';$confirmar=$_POST['confirmar']??'';if($nombre===''||strlen($usuario)<3||strlen($pass)<10||$pass!==$confirmar){$error='Completa los datos. La contraseña debe tener al menos 10 caracteres y coincidir.';}else{$hash=password_hash($pass,PASSWORD_DEFAULT);$rol='admin';$q=$conn->prepare('INSERT INTO usuarios(nombre,usuario,password,rol) VALUES(?,?,?,?)');$q->bind_param('ssss',$nombre,$usuario,$hash,$rol);if($q->execute()){header('Location: index.php');exit;}$error='No se pudo crear. Verifica que el usuario no exista.';}$n=(int)$conn->query("SELECT COUNT(*) c FROM usuarios WHERE rol='admin'")->fetch_assoc()['c'];}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Crear administrador</title><link rel="stylesheet" href="estilos.css"></head><body><main class="form-card"><div class="marca">Como en <span>Casa</span></div><h1 class="titulo">Configuración inicial</h1><?php if($n>0):?><div class="alerta">Ya existe un administrador. Por seguridad, este formulario está bloqueado.</div><a class="btn btn-vino" href="index.php">Ir al login</a><?php else:?> <p class="muted">Crea tu cuenta de administrador. Este formulario solo funciona mientras no exista ningún administrador.</p><?php if($error):?><div class="alerta error"><?=e($error)?></div><?php endif;?><form method="post"><div class="campo"><label>Nombre completo</label><input name="nombre" required></div><div class="campo"><label>Usuario administrador</label><input name="usuario" required></div><div class="campo"><label>Contraseña segura (mínimo 10 caracteres)</label><input type="password" name="pass" required></div><div class="campo"><label>Confirmar contraseña</label><input type="password" name="confirmar" required></div><button class="btn">Crear administrador</button></form><?php endif;?></main></body></html>
